Deno.test({
  name: "retrievers model: HTTP errors name the request and status",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi({
      "GET /api/libraries/test-id-123": {
        status: 500,
        json: { message: "boom" },
      },
    }, async ({ run }) => {
      const err = await assertRejects(
        () => run("get_library", { "library_id": "test-id-123" }),
        Error,
      );
      assertStringIncludes(err.message, "GET /api/libraries/test-id-123");
      assertStringIncludes(err.message, "500");
      assertStringIncludes(err.message, "boom");
    });
  },
});

